require __DIR__.'/../app/bootstrap.php';$ticket=trim((string)($_GET['ticket']??''));$d=db_load();$branch=branch_current($d);$publicBranchSlug=(string)($branch['slug']??'');$branchHome=branch_slug_path($branch);$c=null;foreach($d['checkins'] as $x)if(($x['ticket']??'')===$ticket){$c=$x;break;}
$callMsg='';$callErr='';
if($_SERVER['REQUEST_METHOD']==='POST' && $c){csrf_check();$kind=(string)($_POST['call']??'staff');try{if(!in_array($kind,['staff','pr'],true))throw new RuntimeException('คำขอไม่ถูกต้อง');$cid=(int)$c['id'];$ticket0=(string)$c['ticket'];db_mutate(function($x)use($kind,$cid,$ticket0,$c){$x['service_calls'][]=['id'=>next_id($x['service_calls']??[]),'checkin_id'=>$cid,'type'=>$kind,'status'=>'open','created_at'=>date('c')];if($kind==='pr' && !empty($c['pr_id'])){$pr=op_find_pr($x,(int)$c['pr_id']);$uid=(int)($pr['user_id']??0);op_notify($x,$uid?:null,'pr','customer_call','ลูกค้าเรียก PR · '.$ticket0,['checkin_id'=>$cid]);}else{op_notify($x,null,'staff','customer_call','ลูกค้าเรียกพนักงาน · '.$ticket0,['checkin_id'=>$cid]);}$x['audit'][]=['at'=>date('c'),'action'=>'customer_call_'.$kind,'checkin_id'=>$cid];return $x;});$callMsg=$kind==='pr'?'ส่งคำขอเรียก PR แล้ว':'ส่งคำขอเรียกพนักงานแล้ว';$d=db_load();}catch(Throwable $e){$callErr=$e->getMessage();}}
$labels=['pending'=>['รอทีมงาน','เราได้รับ Check-in แล้ว พนักงานกำลังจัดคิวให้คุณ','⌁'],'rejected'=>['กำลังจัด PR ใหม่','PR คนแรกไม่สะดวก ทีมงานกำลังเลือกคนใหม่ให้','↻'],'assigned'=>['ส่งงานให้ PR แล้ว','กำลังรอ PR ตอบรับงานของคุณ','→'],'accepted'=>['PR รับงานแล้ว','PR กำลังเตรียมเข้าดูแลโต๊ะของคุณ','✓'],'in_service'=>['กำลังให้บริการ','PR กำลังดูแลโต๊ะของคุณอยู่','✦'],'completed'=>['เสร็จสิ้น','ขอบคุณที่ใช้บริการ MR BAR','♥'],'cancelled'=>['รายการถูกยกเลิก','กรุณาติดต่อพนักงานหากต้องการความช่วยเหลือ','×']];
?><!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="15"><link rel="stylesheet" href="assets/customer.css"><title>Status — MR BAR</title><style>.status-steps{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:22px 0}.status-steps span{padding:10px 5px;border:1px solid #ffffff14;border-radius:12px;color:#6f6b7d;font-size:10px;text-align:center}.status-steps span.on{border-color:#ba45ff55;color:#fff;background:#9b31ff14;box-shadow:0 0 24px #9338ff18}.status-icon{font-size:52px;margin:8px 0;text-shadow:0 0 30px #b337ff}.refresh-note{font-size:10px;color:#716e7e;margin-top:15px}@media(max-width:520px){.status-steps{grid-template-columns:1fr 1fr}}</style></head><body><div class="noise"></div><div class="ambient ambient-a"></div><main class="maintenance"><div class="glass hero-card" style="max-width:620px;width:100%;padding:42px 28px"><p class="eyebrow">GUEST LIVE STATUS</p><?php if(!$c):?><h1>ไม่พบรายการ</h1><p>กรุณาตรวจสอบเลข Check-in อีกครั้ง</p><a class="neon-btn" style="text-decoration:none;display:flex" href="<?=h($branchHome)?>"><span>กลับหน้าร้าน</span></a><?php else:$t=op_find_table($d,(int)$c['table_id']);$p=op_find_pr($d,(int)($c['pr_id']??0));$st=(string)$c['status'];$info=$labels[$st]??[$st,'กำลังอัปเดตสถานะ','◉'];$progress=['pending'=>1,'rejected'=>1,'assigned'=>2,'accepted'=>3,'in_service'=>4,'completed'=>4,'cancelled'=>0][$st]??1;?><div class="status-icon"><?=h($info[2])?></div><h1><?=h($info[0])?></h1><p><?=h($info[1])?></p><div style="margin:22px auto;padding:18px;border:1px solid #ffffff12;border-radius:18px;background:#ffffff05"><div class="eyebrow">CHECK-IN</div><div style="font-size:23px;font-weight:900;margin:6px 0"><?=h((string)$c['ticket'])?></div><p style="margin:0">คุณ <?=h((string)$c['guest_name'])?> · โต๊ะ <?=h((string)($t['code']??'-'))?></p><?php if($p):?><p style="margin:8px 0 0">PR: <b><?=h((string)$p['name'])?></b></p><?php endif;?></div><?php if($callMsg):?><div style="padding:12px;border:1px solid #42ff9b66;border-radius:14px;margin:12px 0">✓ <?=h($callMsg)?></div><?php endif;?><?php if($callErr):?><div style="padding:12px;border:1px solid #ff477e66;border-radius:14px;margin:12px 0">⚠ <?=h($callErr)?></div><?php endif;?><div class="status-steps"><span class="<?=$progress>=1?'on':''?>">1 CHECK-IN</span><span class="<?=$progress>=2?'on':''?>">2 ASSIGN PR</span><span class="<?=$progress>=3?'on':''?>">3 ACCEPT</span><span class="<?=$progress>=4?'on':''?>">4 SERVICE</span></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:14px 0"><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="public_branch" value="<?=h($publicBranchSlug)?>"><input type="hidden" name="call" value="staff"><button class="neon-btn" style="width:100%"><span>🔔 เรียกพนักงาน</span></button></form><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="public_branch" value="<?=h($publicBranchSlug)?>"><input type="hidden" name="call" value="pr"><button class="neon-btn" style="width:100%"><span>♛ เรียก PR</span></button></form></div><a class="neon-btn" style="text-decoration:none;display:flex" href="status.php?ticket=<?=urlencode($ticket)?>&amp;public_branch=<?=urlencode($publicBranchSlug)?>"><span>รีเฟรชสถานะ</span><b>↻</b></a><p class="refresh-note">หน้านี้จะอัปเดตอัตโนมัติทุก 15 วินาที</p><a class="back" href="<?=h($branchHome)?>">กลับหน้าร้าน</a><?php endif;?></div></main></body></html>
